interface CollapsibleSidePanelProps {
  panels: PanelItem[];
  activeKey: string;
  onActiveKeyChange: (key: string) => void;
  className?: string;
}

export function CollapsibleSidePanel({
  panels,
  activeKey,
  onActiveKeyChange,
  className,
}: CollapsibleSidePanelProps) {
  const isMobile = useMobile();
  const activePanel = panels.find((p) => p.key === activeKey);

  if (!panels || panels.length === 0) {
    return null;
  }

  return (
    <div className={cn(
      "self-start flex flex-row bg-background border rounded-lg shadow-sm",
      isMobile && "mb-16",
      className
    )}>
      <div className="flex flex-col gap-2 border-r border-border/60 bg-muted/10 p-2">
        <TooltipProvider>
          {panels.map((panel) => (
            <Tooltip key={panel.key} delayDuration={0}>
              <TooltipTrigger asChild>
                <Button variant={activeKey === panel.key ? 'secondary' : 'ghost'} size="icon" onClick={() => onActiveKeyChange(panel.key)} aria-label={panel.title} className="h-9 w-9">
                  {panel.icon}
                </Button>
              </TooltipTrigger>
              <TooltipContent side="right">
                <p>{panel.title}</p>
              </TooltipContent>
            </Tooltip>
          ))}
        </TooltipProvider>
      </div>
      <div className="flex-1 p-4 sm:p-5 w-px">
        {activePanel?.content}
      </div>
    </div>
  );
}

