        const behaviors = project.behaviors ? [...project.behaviors] : [];
        behaviors[index] = { ...behaviors[index], ...updates };
        updateProject(p => p.with({ behaviors }));
    };

    const addBehavior = () => {
        const behaviors = project.behaviors ? [...project.behaviors] : [];
